package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.WorkerAuthorizationService.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Actual day authority and original P1/P2 SQL to worker; model terminal genesis and Sender are fictional. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class SourceDayWorkerIntegrationMySqlTest {
    SourceDayPipelineIntegrationMySqlTest f;GenerationJdbcStoreTest db;String root;
    DispatchReadinessService readiness;JdbcWorkerState state;WorkerJdbcStore store;WorkerAuthorizationService worker;
    void setup()throws Exception{f=new SourceDayPipelineIntegrationMySqlTest();f.setup(false);f.projectFictionalAppliedMember();var prepared=f.preparation.prepareValue(f.child(),f.day.run(),f.day.original.ref,0);root=prepared.root().ownerId();db=f.f.db;WorkerCandidateSelectionScopeTest.installWorker(db);state=new JdbcWorkerState(db.source);readiness=f.dispatch();restart();}
    void restart(){store=new WorkerJdbcStore(state,new JdbcJobRecords(db.source),"fictional-actual-day-worker",()->false,readiness,f.f.clock,f.day.manager);worker=new WorkerAuthorizationService(db.writes,store,f.f.clock,n->0,()->true);}
    SharedWriteExecutor.ActionContext action(){return new SharedWriteExecutor.ActionContext("fictional-actual-day-claim","fictional-actual-day-claim-ref",null);}
    void loseRegistration(){db.jdbc.update("DELETE FROM request_receipts WHERE actor_id='source-day-register'");}
    @Test void actualOriginalDayClaimSendAndRestartUseOneBudgetAndOneSendReceipt()throws Exception{setup();var claim=worker.claim(action());assertEquals(State.CLAIMED,claim.state());assertEquals(root,claim.permit().identity().rootId());var identity=claim.permit().identity();var sends=new AtomicInteger();assertEquals(State.SENT,worker.dispatch(claim.permit(),json->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(identity.frozenRequestJson(),json);sends.incrementAndGet();return "fictional-accepted-result";}).state());assertEquals(1,sends.get());assertEquals(1,new JdbcJobRecords(db.source).byId(root).callCount());assertEquals(1,db.count("target_type='worker_claim'"));assertEquals(1,db.count("target_type='worker_send'"));restart();var replay=worker.claim(action());assertEquals(identity,replay.permit().identity());assertEquals(State.UNKNOWN,worker.dispatch(replay.permit(),json->{fail("durable original send cannot repeat");return null;}).state());assertEquals(1,sends.get());}
    @Test void actualOriginalRunReceiptLostAfterCaptureCannotReserveBudgetOrSlot()throws Exception{setup();var scope=store.captureClaim(action(),f.f.clock.instant());var candidates=db.writes.execute(new SharedWriteExecutor.ActionContext("fictional-actual-day-candidates",root,null),key->null,c->scope.candidates(f.f.clock.instant()));assertEquals(1,candidates.size());loseRegistration();assertThrows(RuntimeException.class,()->db.writes.execute(action(),key->null,c->scope.reserve(candidates.getFirst(),"fictional-hint",f.f.clock.instant().plusSeconds(150),f.f.clock.instant(),c.actionKey())));assertEquals(0,new JdbcJobRecords(db.source).byId(root).callCount());assertEquals("free",state.slot().state());assertEquals(0,db.count("target_type='worker_claim'"));assertEquals(0,db.count("target_type='worker_send'"));}
    @Test void actualOriginalRunReceiptLostAfterClaimNeverAuthorizesOrCallsSender()throws Exception{setup();var claim=worker.claim(action());assertEquals(State.CLAIMED,claim.state());loseRegistration();assertEquals(State.UNKNOWN,worker.dispatch(claim.permit(),json->{fail("lost actual original registration cannot send");return null;}).state());assertFalse(state.authorized(claim.permit().attemptId()));assertEquals(0,db.count("target_type='worker_send'"));assertEquals(1,new JdbcJobRecords(db.source).byId(root).callCount());assertEquals("occupied",state.slot().state());}
    @Test void actualDaySendReceiptFailureRollsBackAndSameClaimRecovers()throws Exception{setup();var claim=worker.claim(action());assertEquals(State.CLAIMED,claim.state());db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_actual_day_send_refused CHECK (target_type IS NULL OR target_type<>'worker_send')");assertEquals(State.UNKNOWN,worker.dispatch(claim.permit(),json->{fail("failed durable send receipt cannot send");return null;}).state());assertFalse(state.authorized(claim.permit().attemptId()));assertEquals(0,db.count("target_type='worker_send'"));db.jdbc.execute("ALTER TABLE jobs DROP CHECK fictional_actual_day_send_refused");restart();var replay=worker.claim(action());assertEquals(claim.permit().identity(),replay.permit().identity());assertEquals(State.SENT,worker.dispatch(replay.permit(),json->"fictional-recovered-result").state());assertEquals(1,db.count("target_type='worker_send'"));assertEquals(1,new JdbcJobRecords(db.source).byId(root).callCount());}
}
